import{_ as t,o as n,c as o,a2 as s}from"./chunks/framework.BXzK3EA4.js";const i="/assets/cec62239767828bf.cSNT0bVW.png",a="/assets/82fd0ae390468e95.-A5MDDza.png",p="/assets/1fef0e63aa431e90.CMOZjBE1.png",c="/assets/3fbbf14cb6c0dada.D9NPt0ke.png",r="/assets/b2afc1b626d94611.CXqWCanG.png",f=JSON.parse('{"title":"Setting up Ping Block on Windows System","description":"","frontmatter":{"title":"Setting up Ping Block on Windows System"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/windows/setting-up-ping-block-on-windows-system.md","filePath":"operations-knowledge-base/operating-system/windows/setting-up-ping-block-on-windows-system.md","lastUpdated":1794292919000}'),l={name:"operations-knowledge-base/operating-system/windows/setting-up-ping-block-on-windows-system.md"};function d(m,e,g,w,u,h){return n(),o("div",null,[...e[0]||(e[0]=[s('<p>To prevent hackers from discovering and attacking the machine through network ping scanning, you can disable the ping command on the local machine.</p><p><img src="'+i+'" alt=""></p><p>1.Press the Win+R shortcut key on your computer desktop to open the Run window. Type &quot;cmd&quot; in the search box and click OK.</p><p><img src="'+a+'" alt=""></p><p>2.Enter the following command in the command prompt window.：</p><ul><li>netsh advfirewall firewall add rule name=&quot;ICMP Allow incoming V4 echo request&quot; protocol=icmpv4:8,any dir=in action=block</li></ul><p>This command adds a new rule on top of the existing rules. If you want to restore the ability to ping, you can simply delete this rule</p><ul><li>netsh advfirewall firewall del rule name=&quot;ICMP Allow incoming V4 echo request&quot;</li></ul><p><img src="'+p+'" alt=""></p><p>3.At this point, if we check the IP, we can see that ping is blocked. However, if we want to test the IP connectivity, we can perform a ping test on a specific port, and we can see that it is reachable. If we want to restore the ping block, we can simply enable the aforementioned rule again.</p><p><img src="'+c+'" alt=""></p><p><img src="'+r+'" alt=""></p>',12)])])}const k=t(l,[["render",d]]);export{f as __pageData,k as default};
